from playwright.sync_api import sync_playwright
BOOT='''window._q=[];window._t=0;window.requestAnimationFrame=f=>_q.push(f);window.advance=n=>{for(let i=0;i<n;i++){_t+=1000/60;const q=_q.splice(0);q.forEach(f=>f(_t));}};
window.pathTo=(s,to)=>{const sx=Math.floor(s.player.x),sy=Math.floor(s.player.y),tx=Math.floor(to.x),ty=Math.floor(to.y),q=[[sx,sy]],parents=new Map([[sx+','+sy,null]]);for(let i=0;i<q.length;i++){const [x,y]=q[i];if(x===tx&&y===ty){let k=x+','+y;const out=[];while(parents.get(k)!==null){const [a,b]=k.split(',').map(Number);out.unshift({x:a+.5,y:b+.5});k=parents.get(k);}return out;}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const xx=x+dx,yy=y+dy,k=xx+','+yy;if(s.map[yy]?.[xx]===0&&!parents.has(k)){parents.set(k,x+','+y);q.push([xx,yy]);}}}return null;};
window.driveTo=(target,max=16000)=>{let s=ghostState(),path=pathTo(s,target);if(!path)throw Error('unreachable');path.unshift({x:Math.floor(s.player.x)+.5,y:Math.floor(s.player.y)+.5});for(let i=0;i<max;i++){s=ghostState();if(s.mode!=='playing')break;for(const g of s.ghosts)if(s.map[Math.floor(g.y)]?.[Math.floor(g.x)]!==0)throw Error('ghost crossed a wall');while(path.length&&Math.hypot(path[0].x-s.player.x,path[0].y-s.player.y)<.065)path.shift();if(!path.length)break;const p=path[0],dx=p.x-s.player.x,dy=p.y-s.player.y;const goal=Math.abs(dx)>.065?(dx>0?'ArrowRight':'ArrowLeft'):(dy>0?'ArrowDown':'ArrowUp');for(const key of ['ArrowRight','ArrowLeft','ArrowDown','ArrowUp'])window.dispatchEvent(new KeyboardEvent(key===goal?'keydown':'keyup',{code:key,bubbles:true}));if(s.cooldown===0)window.dispatchEvent(new KeyboardEvent('keydown',{code:'ShiftLeft',bubbles:true}));advance(1);}for(const code of ['ArrowRight','ArrowLeft','ArrowDown','ArrowUp'])window.dispatchEvent(new KeyboardEvent('keyup',{code,bubbles:true}));return ghostState();};'''
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1000,'height':950});page.add_init_script(BOOT);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8002/ghost/');page.locator('#action').click()
 page.keyboard.down('ArrowLeft');page.evaluate('advance(20)');page.keyboard.up('ArrowLeft');assert page.evaluate('ghostState().player.x')>=1.23;page.keyboard.down('ArrowRight');page.evaluate('advance(6)');page.keyboard.up('ArrowRight');
 assert page.evaluate('ghostState().keys.every(k=>pathTo(ghostState(),k)!==null)&&pathTo(ghostState(),ghostState().exit)!==null');hide_y=page.evaluate('ghostState().player.y');page.locator('#hide').click();page.keyboard.down('ArrowUp');page.evaluate('advance(120)');page.keyboard.up('ArrowUp');assert page.evaluate('ghostState().hidden');assert page.evaluate('ghostState().player.y')==hide_y;page.locator('#hide').click();page.locator('#pause').click();t=page.evaluate('ghostState().elapsed');page.evaluate('advance(120)');assert page.evaluate('ghostState().elapsed')==t;page.locator('#action').click();page.screenshot(path='/tmp/ghost-desktop.png');print('PASS connected map, hiding, pause and resume',flush=True)
 for attempt in range(20):
  s=page.evaluate('ghostState()')
  if s['mode']=='won':break
  if s['mode']=='caught':
   keys_before=sum(k['got'] for k in s['keys']);page.locator('#action').click();assert page.evaluate('ghostState().keys.filter(k=>k.got).length')==keys_before;s=page.evaluate('ghostState()');print('retry, keys preserved:',keys_before,flush=True)
  target=page.evaluate('(()=>{const s=ghostState();return s.keys.filter(k=>!k.got).sort((a,b)=>pathTo(s,a).length-pathTo(s,b).length)[0]||s.exit;})()');result=page.evaluate('(target)=>driveTo(target)',target);print('travel',attempt,result['mode'],sum(k['got'] for k in result['keys']),flush=True)
 s=page.evaluate('ghostState()');assert s['mode']=='won',s;assert all(k['got'] for k in s['keys']);print('PASS actual maze escape',s['elapsed'],'seconds',s['retries'],'retries',flush=True)
 page.reload();assert page.evaluate('ghostState().best.gentle')>0
 m=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);m.add_init_script(BOOT);m.on('pageerror',lambda e:errors.append(str(e)));m.goto('http://127.0.0.1:8002/ghost/');m.locator('[data-mode="spooky"]').tap();m.locator('#action').tap();assert m.evaluate('ghostState().difficulty')=='spooky';m.locator('#hide').tap();assert m.evaluate('ghostState().hidden');m.locator('#hide').tap();m.locator('#dash').tap();assert m.evaluate('ghostState().boost')>0
 cdp=m.context.new_cdp_session(m);r=m.locator('#up').bounding_box();cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':r['x']+r['width']/2,'y':r['y']+r['height']/2,'id':1}]});m.evaluate('advance(10)');assert m.evaluate('ghostState().player.y')<13.5;cdp.send('Input.dispatchTouchEvent',{'type':'touchCancel','touchPoints':[]});assert not m.evaluate('ghostState().held');m.screenshot(path='/tmp/ghost-mobile.png');assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors;print('PASS mobile touch, dash, hiding, difficulty, layout and no JS errors');b.close()
